begin;
-- Uploaded originals form a separate document source. No offer acceptance or
-- native template is fabricated to fit this workflow.
create table private.uploaded_pdf_sources(
 id uuid primary key,company_id uuid not null references public.companies(id),deal_id uuid not null,customer_id uuid not null,
 created_by uuid not null references auth.users(id),company_name text not null,recipient_name text not null,recipient_email text not null,
 filename text not null,original_sha256 text not null,byte_size integer not null check(byte_size between 5 and 4194304),page_count integer not null check(page_count between 1 and 100),
 object_path text not null unique,canonical_content text not null,document_hash text not null,
 created_at timestamptz not null default clock_timestamp(),expires_at timestamptz not null default(clock_timestamp()+interval '7 days'),
 foreign key(company_id,deal_id) references public.deals(company_id,id),foreign key(company_id,customer_id) references public.customers(company_id,id),
 check(filename=btrim(filename) and length(filename) between 5 and 160 and filename !~ '[[:cntrl:]/\\]' and lower(right(filename,4))='.pdf'),
 check(original_sha256 ~ '^[a-f0-9]{64}$'),check(document_hash=encode(sha256(convert_to(canonical_content,'UTF8')),'hex')),
 check(recipient_email=lower(btrim(recipient_email)) and recipient_email ~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$')
);
create index uploaded_pdf_source_deal on private.uploaded_pdf_sources(company_id,deal_id,created_at desc);
create table private.uploaded_pdf_signatures(source_id uuid not null references private.uploaded_pdf_sources(id),party text not null check(party in('company','customer')),actor_user_id uuid references auth.users(id),full_name text not null,signed_at timestamptz not null default clock_timestamp(),document_hash text not null,consent_version text not null check(consent_version='2026-11-13'),primary key(source_id,party),check(private.contract_pdf_name_supported_v1(full_name)),check((party='company')=(actor_user_id is not null)));
create table private.uploaded_pdf_requests(actor_user_id uuid not null references auth.users(id),request_id uuid not null,payload jsonb not null,receipt jsonb not null,primary key(actor_user_id,request_id));
create table private.uploaded_pdf_guest_requests(source_id uuid not null references private.uploaded_pdf_sources(id),request_id uuid not null,payload jsonb not null,receipt jsonb not null,primary key(source_id,request_id));
create table private.uploaded_pdf_tokens(source_id uuid primary key references private.uploaded_pdf_sources(id),token_sha256 text not null check(token_sha256 ~ '^[a-f0-9]{64}$'));
create table private.uploaded_pdf_cancellations(source_id uuid primary key references private.uploaded_pdf_sources(id),actor_user_id uuid not null references auth.users(id),reason text not null check(length(reason) between 2 and 1000),created_at timestamptz not null default clock_timestamp());
create table private.uploaded_pdf_artifacts(source_id uuid primary key references private.uploaded_pdf_sources(id),pdf_path text not null,pdf_sha256 text not null check(pdf_sha256 ~ '^[a-f0-9]{64}$'),evidence_path text not null,evidence_sha256 text not null check(evidence_sha256 ~ '^[a-f0-9]{64}$'),created_at timestamptz not null default clock_timestamp());
create table private.uploaded_pdf_emails(id uuid primary key default gen_random_uuid(),source_id uuid not null references private.uploaded_pdf_sources(id),kind text not null check(kind in('invitation','completed')),status text not null default 'queued' check(status in('queued','processing','sent','rejected','unknown')),first_attempt_at timestamptz,lease_id uuid,lease_until timestamptz,body_sha256 text,provider_id text,unique(source_id,kind),check((status='processing')=(lease_id is not null and lease_until is not null)));

-- No exposed data tables or direct storage policies. Server IO uses the service
-- client only after fresh user/capability authorization and verifies every byte.
do $$declare t text;begin foreach t in array array['uploaded_pdf_sources','uploaded_pdf_signatures','uploaded_pdf_requests','uploaded_pdf_guest_requests','uploaded_pdf_tokens','uploaded_pdf_cancellations','uploaded_pdf_artifacts','uploaded_pdf_emails'] loop execute format('alter table private.%I enable row level security',t);execute format('revoke all on private.%I from public,anon,authenticated,service_role',t);end loop;end$$;
do $$declare t text;begin foreach t in array array['uploaded_pdf_sources','uploaded_pdf_signatures','uploaded_pdf_requests','uploaded_pdf_guest_requests','uploaded_pdf_tokens','uploaded_pdf_cancellations','uploaded_pdf_artifacts'] loop execute format('create trigger immutable_uploaded_pdf before update or delete on private.%I for each row execute function private.sale_contract_immutable()',t);end loop;end$$;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('uploaded-contracts','uploaded-contracts',false,16777216,array['application/pdf','application/json']) on conflict(id) do nothing;
-- A same-name manually configured bucket must not silently make originals
-- public or cause completion to fail after signing. Lock and verify the final
-- row, including a concurrent ON CONFLICT winner; never rewrite its settings.
do $$declare b storage.buckets;required text[]:=array['application/pdf','application/json'];begin
 select * into b from storage.buckets where id='uploaded-contracts' for update;
 if not found or b.public is distinct from false or b.file_size_limit is null
  or b.file_size_limit<4456448 or b.file_size_limit>16777216
  or b.allowed_mime_types is null or not(b.allowed_mime_types @> required and required @> b.allowed_mime_types)
 then raise exception 'Existing uploaded-contracts bucket configuration is incompatible; no settings changed' using errcode='55000';end if;
end$$;


create function private.uploaded_pdf_objects_guard() returns trigger language plpgsql security definer set search_path='' as $$begin if old.bucket_id='uploaded-contracts' then raise exception 'Immutable uploaded PDF artifact' using errcode='55000';end if;if tg_op='UPDATE' then if new.bucket_id='uploaded-contracts' then raise exception 'Immutable uploaded PDF artifact' using errcode='55000';end if;return new;end if;return old;end$$;
create trigger uploaded_pdf_objects_immutable before update or delete on storage.objects for each row execute function private.uploaded_pdf_objects_guard();

create function private.uploaded_pdf_actor(c uuid) returns uuid language plpgsql security invoker set search_path='' as $$declare a uuid;begin select actor into a from private.sale_contract_access(c,true);return a;end$$;
create function private.uploaded_pdf_service() returns void language plpgsql security invoker set search_path='' as $$begin if auth.role() is distinct from 'service_role' then raise exception 'Service required' using errcode='42501';end if;end$$;
create function private.uploaded_pdf_actor_valid(c uuid,a uuid) returns boolean language sql security definer set search_path='' as $$select exists(select 1 from auth.users u join public.memberships m on m.user_id=u.id and m.company_id=c and m.status='active' and m.role in('owner','admin') join public.companies co on co.id=c and co.status='active' where u.id=a and u.email_confirmed_at is not null and not coalesce(u.is_anonymous,false) and not coalesce(u.is_sso_user,false) and(u.banned_until is null or u.banned_until<=clock_timestamp()) and private.account_effective_status(a)='approved')$$;
create function private.uploaded_pdf_current(s private.uploaded_pdf_sources,guest boolean default false) returns boolean language sql security invoker set search_path='' as $$select (not exists(select 1 from private.uploaded_pdf_cancellations where source_id=s.id) or(not guest and exists(select 1 from private.uploaded_pdf_signatures where source_id=s.id and party='customer'))) and exists(select 1 from public.deals d join public.companies c on c.id=d.company_id and c.status='active' join public.customers u on u.company_id=d.company_id and u.id=d.customer_id where d.company_id=s.company_id and d.id=s.deal_id and d.status<>'cancelled' and ((not guest and exists(select 1 from private.uploaded_pdf_signatures where source_id=s.id and party='customer')) or (u.id=s.customer_id and lower(btrim(u.email))=s.recipient_email and u.name=s.recipient_name and (exists(select 1 from private.uploaded_pdf_signatures where source_id=s.id and party='customer') or private.uploaded_pdf_actor_valid(s.company_id,s.created_by))))) and(not guest or s.expires_at>clock_timestamp())$$;
create function private.uploaded_pdf_json(s private.uploaded_pdf_sources) returns jsonb language sql security invoker set search_path='' as $$select jsonb_build_object('id',s.id,'companyId',s.company_id,'dealId',s.deal_id,'customerId',s.customer_id,'companyName',s.company_name,'recipientName',s.recipient_name,'recipientEmail',s.recipient_email,'filename',s.filename,'originalSha256',s.original_sha256,'byteSize',s.byte_size,'pageCount',s.page_count,'objectPath',s.object_path,'documentHash',s.document_hash,'canonicalContent',s.canonical_content,'createdAt',s.created_at,'expiresAt',s.expires_at,'linkRevoked',exists(select 1 from private.uploaded_pdf_cancellations where source_id=s.id),'status',case when not private.uploaded_pdf_current(s) or(s.expires_at<=clock_timestamp() and not exists(select 1 from private.uploaded_pdf_signatures where source_id=s.id and party='customer')) then 'unavailable' when exists(select 1 from private.uploaded_pdf_signatures where source_id=s.id and party='customer') then 'completed' when exists(select 1 from private.uploaded_pdf_signatures where source_id=s.id and party='company') then 'pending' else 'draft' end,'companySignature',(select jsonb_build_object('actorId',actor_user_id,'fullName',full_name,'signedAt',signed_at,'documentHash',document_hash,'consentVersion',consent_version) from private.uploaded_pdf_signatures where source_id=s.id and party='company'),'customerSignature',(select jsonb_build_object('actorId',actor_user_id,'fullName',full_name,'signedAt',signed_at,'documentHash',document_hash,'consentVersion',consent_version) from private.uploaded_pdf_signatures where source_id=s.id and party='customer'),'delivery',(select status from private.uploaded_pdf_emails where source_id=s.id and kind=case when exists(select 1 from private.uploaded_pdf_signatures where source_id=s.id and party='customer') then 'completed' else 'invitation' end),'archive',(select jsonb_build_object('pdfPath',pdf_path,'pdfSha256',pdf_sha256,'evidencePath',evidence_path,'evidenceSha256',evidence_sha256) from private.uploaded_pdf_artifacts where source_id=s.id))$$;

create function public.list_uploaded_pdf_signings(p_company_id uuid,p_deal_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$declare a uuid;u record;begin a:=private.uploaded_pdf_actor(p_company_id);select c.name,c.email into u from public.deals d join public.customers c on c.company_id=d.company_id and c.id=d.customer_id where d.company_id=p_company_id and d.id=p_deal_id;if not found then raise exception 'Deal denied' using errcode='42501';end if;return jsonb_build_object('companyId',p_company_id,'dealId',p_deal_id,'actorId',a,'recipientName',u.name,'recipientEmail',coalesce(lower(btrim(u.email)),''),'documents',(select coalesce(jsonb_agg(private.uploaded_pdf_json(x) order by x.created_at desc,x.id desc),'[]') from(select * from private.uploaded_pdf_sources where company_id=p_company_id and deal_id=p_deal_id order by created_at desc,id desc limit 20)x));end$$;
create function public.get_uploaded_pdf_source(p_company_id uuid,p_source_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$declare a uuid;s private.uploaded_pdf_sources;begin a:=private.uploaded_pdf_actor(p_company_id);select * into s from private.uploaded_pdf_sources where id=p_source_id and company_id=p_company_id;if not found then raise exception 'Source denied' using errcode='42501';end if;return jsonb_build_object('actorId',a,'source',private.uploaded_pdf_json(s));end$$;
create function public.register_uploaded_pdf_source(p_actor_id uuid,p_company_id uuid,p_deal_id uuid,p_source_id uuid,p_filename text,p_sha256 text,p_byte_size integer,p_page_count integer) returns jsonb language plpgsql security definer set search_path='' as $$declare s private.uploaded_pdf_sources;u record;canonical text;path text;begin perform private.uploaded_pdf_service();if not private.uploaded_pdf_actor_valid(p_company_id,p_actor_id) then raise exception 'Actor denied' using errcode='42501';end if;perform pg_advisory_xact_lock(hashtextextended('uploaded-pdf:'||p_source_id::text,0));select * into s from private.uploaded_pdf_sources where id=p_source_id;if found then if s.company_id<>p_company_id or s.deal_id<>p_deal_id or s.created_by<>p_actor_id or s.filename<>p_filename or s.original_sha256<>p_sha256 or s.byte_size<>p_byte_size or s.page_count<>p_page_count then raise exception 'Upload request changed' using errcode='40001';end if;return private.uploaded_pdf_json(s);end if;
 select c.id as customer_id,c.name,c.email,co.name as company_name into u from public.deals d join public.customers c on c.company_id=d.company_id and c.id=d.customer_id join public.companies co on co.id=d.company_id where d.company_id=p_company_id and d.id=p_deal_id and d.status in('draft','reserved') for update of d;
 if not found then raise exception 'Deal unavailable' using errcode='42501';end if;
 path:=p_company_id::text||'/uploaded-pdfs/'||p_source_id::text||'/original-'||p_sha256||'.pdf';
 if not exists(select 1 from storage.objects where bucket_id='uploaded-contracts' and name=path) then raise exception 'Original not stored' using errcode='40001';end if;
 canonical:=jsonb_build_object('schemaVersion',1,'kind','uploaded_pdf','sourceId',p_source_id,'companyId',p_company_id,'dealId',p_deal_id,'customerId',u.customer_id,'filename',p_filename,'originalSha256',p_sha256,'byteSize',p_byte_size,'pageCount',p_page_count,'recipientName',u.name,'recipientEmail',lower(btrim(u.email)))::text;
 insert into private.uploaded_pdf_sources(id,company_id,deal_id,customer_id,created_by,company_name,recipient_name,recipient_email,filename,original_sha256,byte_size,page_count,object_path,canonical_content,document_hash) values(p_source_id,p_company_id,p_deal_id,u.customer_id,p_actor_id,u.company_name,u.name,lower(btrim(u.email)),p_filename,p_sha256,p_byte_size,p_page_count,path,canonical,encode(sha256(convert_to(canonical,'UTF8')),'hex')) returning * into s;return private.uploaded_pdf_json(s);end$$;
create function public.request_uploaded_pdf_signing(p_company_id uuid,p_source_id uuid,p_document_hash text,p_full_name text,p_acknowledged boolean,p_request_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$declare a uuid;s private.uploaded_pdf_sources;p jsonb;r jsonb;begin a:=private.uploaded_pdf_actor(p_company_id);if p_request_id is null or p_acknowledged is distinct from true or not private.contract_pdf_name_supported_v1(p_full_name) then raise exception 'Review required' using errcode='22023';end if;perform pg_advisory_xact_lock(hashtextextended('uploaded-pdf-request:'||a::text||':'||p_request_id::text,0));p:=jsonb_build_object('sourceId',p_source_id,'companyId',p_company_id,'documentHash',p_document_hash,'fullName',p_full_name,'acknowledged',true);select receipt into r from private.uploaded_pdf_requests where actor_user_id=a and request_id=p_request_id and payload=p;if found then return r;end if;if exists(select 1 from private.uploaded_pdf_requests where actor_user_id=a and request_id=p_request_id) then raise exception 'Request changed' using errcode='40001';end if;
 select * into s from private.uploaded_pdf_sources where id=p_source_id and company_id=p_company_id for update;if not found then raise exception 'Source denied' using errcode='42501';end if;if s.document_hash<>p_document_hash or not private.uploaded_pdf_current(s,true) or exists(select 1 from private.uploaded_pdf_signatures where source_id=s.id) then raise exception 'Source changed' using errcode='40001';end if;
 insert into private.uploaded_pdf_signatures(source_id,party,actor_user_id,full_name,document_hash,consent_version) values(s.id,'company',a,p_full_name,s.document_hash,'2026-11-13');insert into private.uploaded_pdf_emails(source_id,kind) values(s.id,'invitation');r:=jsonb_build_object('actorId',a,'requestId',p_request_id,'source',private.uploaded_pdf_json(s));insert into private.uploaded_pdf_requests values(a,p_request_id,p,r);return r;end$$;
create function public.cancel_uploaded_pdf(p_company_id uuid,p_source_id uuid,p_reason text) returns boolean language plpgsql security definer set search_path='' as $$declare a uuid;s private.uploaded_pdf_sources;begin a:=private.uploaded_pdf_actor(p_company_id);if length(btrim(p_reason)) not between 2 and 1000 then raise exception 'Reason required' using errcode='22023';end if;select * into s from private.uploaded_pdf_sources where id=p_source_id and company_id=p_company_id for update;if not found then raise exception 'Source denied' using errcode='42501';end if;insert into private.uploaded_pdf_cancellations values(s.id,a,btrim(p_reason),clock_timestamp()) on conflict(source_id) do nothing;return true;end$$;

create function private.uploaded_pdf_guest_source(p_source uuid,p_token_sha256 text) returns private.uploaded_pdf_sources language plpgsql security invoker set search_path='' as $$declare s private.uploaded_pdf_sources;begin select x.* into s from private.uploaded_pdf_sources x join private.uploaded_pdf_tokens t on t.source_id=x.id and t.token_sha256=p_token_sha256 where x.id=p_source and exists(select 1 from private.uploaded_pdf_signatures where source_id=x.id and party='company');if not found or not private.uploaded_pdf_current(s,true) then raise exception 'Document unavailable' using errcode='42501';end if;return s;end$$;
create function public.get_uploaded_pdf_guest(p_source_id uuid,p_token_sha256 text) returns jsonb language plpgsql security definer set search_path='' as $$declare s private.uploaded_pdf_sources;begin perform private.uploaded_pdf_service();s:=private.uploaded_pdf_guest_source(p_source_id,p_token_sha256);return private.uploaded_pdf_json(s);end$$;
create function public.sign_uploaded_pdf_guest(p_source_id uuid,p_token_sha256 text,p_document_hash text,p_full_name text,p_acknowledged boolean,p_request_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$declare s private.uploaded_pdf_sources;p jsonb;r jsonb;begin perform private.uploaded_pdf_service();if p_request_id is null or p_acknowledged is distinct from true or not private.contract_pdf_name_supported_v1(p_full_name) then raise exception 'Review required' using errcode='22023';end if;perform pg_advisory_xact_lock(hashtextextended('uploaded-pdf-guest:'||p_source_id::text,0));perform 1 from private.uploaded_pdf_sources where id=p_source_id for update;s:=private.uploaded_pdf_guest_source(p_source_id,p_token_sha256);p:=jsonb_build_object('documentHash',p_document_hash,'fullName',p_full_name,'acknowledged',true);select receipt into r from private.uploaded_pdf_guest_requests where source_id=s.id and request_id=p_request_id and payload=p;if found then return r;end if;if exists(select 1 from private.uploaded_pdf_guest_requests where source_id=s.id and request_id=p_request_id) then raise exception 'Request changed' using errcode='40001';end if;if s.document_hash<>p_document_hash or exists(select 1 from private.uploaded_pdf_signatures where source_id=s.id and party='customer') then raise exception 'Document changed' using errcode='40001';end if;insert into private.uploaded_pdf_signatures(source_id,party,actor_user_id,full_name,document_hash,consent_version) values(s.id,'customer',null,p_full_name,s.document_hash,'2026-11-13');r:=private.uploaded_pdf_json(s);insert into private.uploaded_pdf_guest_requests values(s.id,p_request_id,p,r);return r;end$$;
create function public.archive_uploaded_pdf(p_source_id uuid,p_pdf_sha256 text,p_evidence_sha256 text) returns jsonb language plpgsql security definer set search_path='' as $$declare s private.uploaded_pdf_sources;a private.uploaded_pdf_artifacts;root text;begin perform private.uploaded_pdf_service();select * into s from private.uploaded_pdf_sources where id=p_source_id for update;if not found or not private.uploaded_pdf_current(s) or not exists(select 1 from private.uploaded_pdf_signatures where source_id=s.id and party='customer') then raise exception 'Completed source required' using errcode='42501';end if;root:=s.company_id::text||'/uploaded-pdfs/'||s.id::text||'/';if not exists(select 1 from storage.objects where bucket_id='uploaded-contracts' and name=root||'signed-'||p_pdf_sha256||'.pdf') or not exists(select 1 from storage.objects where bucket_id='uploaded-contracts' and name=root||'evidence-'||p_evidence_sha256||'.json') then raise exception 'Artifacts missing' using errcode='40001';end if;select * into a from private.uploaded_pdf_artifacts where source_id=s.id;if found then if a.pdf_sha256<>p_pdf_sha256 or a.evidence_sha256<>p_evidence_sha256 then raise exception 'Archive changed' using errcode='40001';end if;else insert into private.uploaded_pdf_artifacts(source_id,pdf_path,pdf_sha256,evidence_path,evidence_sha256) values(s.id,root||'signed-'||p_pdf_sha256||'.pdf',p_pdf_sha256,root||'evidence-'||p_evidence_sha256||'.json',p_evidence_sha256);end if;insert into private.uploaded_pdf_emails(source_id,kind) values(s.id,'completed') on conflict(source_id,kind) do nothing;return private.uploaded_pdf_json(s);end$$;
create function public.claim_uploaded_pdf_mail(p_source_id uuid,p_kind text) returns jsonb language plpgsql security definer set search_path='' as $$declare s private.uploaded_pdf_sources;e private.uploaded_pdf_emails;begin perform private.uploaded_pdf_service();select * into s from private.uploaded_pdf_sources where id=p_source_id for update;if not found or not private.uploaded_pdf_current(s,true) then raise exception 'Source unavailable' using errcode='42501';end if;select * into e from private.uploaded_pdf_emails where source_id=s.id and kind=p_kind for update;if not found then return null;end if;if e.status='processing' and e.lease_until<=clock_timestamp() then update private.uploaded_pdf_emails set status='unknown',lease_id=null,lease_until=null where id=e.id returning * into e;end if;if e.status<>'queued' then return jsonb_build_object('status',e.status);end if;if e.first_attempt_at is not null and e.first_attempt_at<=clock_timestamp()-interval '23 hours' then update private.uploaded_pdf_emails set status='unknown' where id=e.id;return jsonb_build_object('status','unknown');end if;update private.uploaded_pdf_emails set status='processing',lease_id=gen_random_uuid(),lease_until=clock_timestamp()+interval '1 minute',first_attempt_at=coalesce(first_attempt_at,clock_timestamp()) where id=e.id returning * into e;return jsonb_build_object('status','processing','id',e.id,'leaseId',e.lease_id,'firstAttemptAt',e.first_attempt_at,'kind',e.kind,'tokenSha256',(select token_sha256 from private.uploaded_pdf_tokens where source_id=s.id),'source',private.uploaded_pdf_json(s));end$$;
create function public.bind_uploaded_pdf_mail(p_email_id uuid,p_lease_id uuid,p_token_sha256 text,p_body_sha256 text) returns boolean language plpgsql security definer set search_path='' as $$declare e private.uploaded_pdf_emails;s private.uploaded_pdf_sources;prior text;begin perform private.uploaded_pdf_service();select * into e from private.uploaded_pdf_emails where id=p_email_id and lease_id=p_lease_id and status='processing' and lease_until>clock_timestamp() for update;if not found then return false;end if;select * into s from private.uploaded_pdf_sources where id=e.source_id;if not private.uploaded_pdf_current(s,true) or p_body_sha256 is null or p_body_sha256 !~ '^[a-f0-9]{64}$' then return false;end if;if e.kind='invitation' then if p_token_sha256 is null or p_token_sha256 !~ '^[a-f0-9]{64}$' then return false;end if;insert into private.uploaded_pdf_tokens values(s.id,p_token_sha256) on conflict(source_id) do nothing;select token_sha256 into prior from private.uploaded_pdf_tokens where source_id=s.id;if prior<>p_token_sha256 then return false;end if;elsif not exists(select 1 from private.uploaded_pdf_tokens where source_id=s.id) then return false;end if;if e.body_sha256 is not null and e.body_sha256<>p_body_sha256 then return false;end if;update private.uploaded_pdf_emails set body_sha256=p_body_sha256 where id=e.id;return true;end$$;
create function public.finish_uploaded_pdf_mail(p_email_id uuid,p_lease_id uuid,p_status text,p_provider_id text) returns boolean language plpgsql security definer set search_path='' as $$begin perform private.uploaded_pdf_service();if p_status not in('sent','queued','rejected','unknown') or(p_status='sent' and(p_provider_id is null or p_provider_id !~ '^[a-zA-Z0-9_-]{1,100}$')) then raise exception 'Invalid result' using errcode='22023';end if;update private.uploaded_pdf_emails set status=p_status,lease_id=null,lease_until=null,provider_id=p_provider_id where id=p_email_id and lease_id=p_lease_id and status='processing' and lease_until>clock_timestamp();return found;end$$;

-- Explicit grants. All helpers remain unexposed; service endpoints cannot be
-- called with a normal user's JWT, even when that user is an owner/admin.
do $$declare f record;begin for f in select p.oid::regprocedure as signature from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='private' and p.proname like 'uploaded_pdf_%' loop execute format('revoke all on function %s from public,anon,authenticated,service_role',f.signature);end loop;end$$;
revoke all on function public.list_uploaded_pdf_signings(uuid,uuid),public.get_uploaded_pdf_source(uuid,uuid),public.request_uploaded_pdf_signing(uuid,uuid,text,text,boolean,uuid),public.cancel_uploaded_pdf(uuid,uuid,text) from public,anon,service_role;
grant execute on function public.list_uploaded_pdf_signings(uuid,uuid),public.get_uploaded_pdf_source(uuid,uuid),public.request_uploaded_pdf_signing(uuid,uuid,text,text,boolean,uuid),public.cancel_uploaded_pdf(uuid,uuid,text) to authenticated;
revoke all on function public.register_uploaded_pdf_source(uuid,uuid,uuid,uuid,text,text,integer,integer),public.get_uploaded_pdf_guest(uuid,text),public.sign_uploaded_pdf_guest(uuid,text,text,text,boolean,uuid),public.archive_uploaded_pdf(uuid,text,text),public.claim_uploaded_pdf_mail(uuid,text),public.bind_uploaded_pdf_mail(uuid,uuid,text,text),public.finish_uploaded_pdf_mail(uuid,uuid,text,text) from public,anon,authenticated;
grant execute on function public.register_uploaded_pdf_source(uuid,uuid,uuid,uuid,text,text,integer,integer),public.get_uploaded_pdf_guest(uuid,text),public.sign_uploaded_pdf_guest(uuid,text,text,text,boolean,uuid),public.archive_uploaded_pdf(uuid,text,text),public.claim_uploaded_pdf_mail(uuid,text),public.bind_uploaded_pdf_mail(uuid,uuid,text,text),public.finish_uploaded_pdf_mail(uuid,uuid,text,text) to service_role;
commit;
